-- ============================================================================
-- 058_proposals_ai_drafted.sql
--
-- Adds ai_drafted tracking to proposals so we can measure AI adoption
-- and edit rate over time.
-- ============================================================================

alter table proposals
  add column if not exists ai_drafted boolean not null default false;

comment on column proposals.ai_drafted is
  'True when the initial title/intro/line items were generated by PROPOSAL_DRAFTER_V1';
